select Grower {
  slug,
  name,
  region: {
    code,
    name,
  },
  batches := (
    select Grower.<grower[is Batch] {
      code,
      kilograms,
      harvested_on,
      certifications,
    }
    filter
      (not exists <optional float64>$min_kilograms
        or .kilograms >= <optional float64>$min_kilograms)
      and (len(<array<str>>$certifications) = 0
        or exists (.certifications intersect array_unpack(<array<str>>$certifications)))
  ),
}
filter .region.code = <str>$region_code
order by .slug

select Batch {
  code,
  kilograms,
  harvested_on,
  certifications,
  grower: {
    slug,
    name,
    region: {
      code,
      name,
    },
  },
  inspection_count := count(Batch.<batch[is Inspection]),
}
filter .code = <str>$code

with
  batch := (select Batch filter .code = <str>$batch_code),
  new_inspection := (
    insert Inspection {
      batch := batch,
      inspector := <str>$inspector,
      passed := <bool>$passed,
      defects := (
        for defect_code in array_unpack(<array<str>>$defect_codes) union (
          insert Defect {
            code := defect_code,
            severity := <int64>$severity,
          }
        )
      ),
    }
  )
select {
  id := new_inspection.id,
  inspector := new_inspection.inspector,
  passed := new_inspection.passed,
  defect_count := count(new_inspection.defects),
  batch_code := batch.code,
}

